{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "Edaravone, a closely related pyrazolone, has an absolute oral bioavailability of 57.3% in Japanese subjects after a 105 mg oral suspension versus 60 mg IV, directly supporting high F for the pyrazolone scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Pirfenidone, the highest-similarity analogue, is rapidly absorbed and displays high oral bioavailability in humans and nonclinical species.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Clobazam, a structurally related N-phenyl heterocycle, has 90-100% oral bioavailability in humans with rapid absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Tolfenamic acid, an N-phenyl carboxylic acid analogue, has absolute oral bioavailability of 55.6% in healthy female volunteers, with other reports up to ~100%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Roquinimex, another N-phenyl heterocycle, shows complete oral bioavailability in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Sulphinpyrazone, an N-phenyl-containing drug, has 90% oral bioavailability from oral and IV dosing experiments in volunteers.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a small, neutral pyrazolone (4-methylaminoantipyrine) with favorable physicochemical properties. The closest pyrazolone analogue edaravone has absolute oral bioavailability ~57% in humans, and multiple structurally related N-phenyl heterocycles (pirfenidone, clobazam, tolfenamic acid, roquinimex, sulphinpyrazone) all show high oral bioavailability. Thus F >=20% is strongly supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule itself.",
    "A single edaravone record describes 'poor bioavailability' for an oral suspension despite absolute F ~57%, suggesting formulation-specific effects; it was not used as low-bioavailability evidence.",
    "First-pass metabolism of the 4-methylamino substituent is not directly assessed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

